const fs = require('fs'); const path = require('path'); const cp = require('child_process');
const parser = require('@babel/parser');
const root = process.env.SB_ROOT;
const paths = cp.execFileSync('git',['ls-files','-z'],{cwd:root,encoding:'utf8'}).split('\0').filter(Boolean);
function walk(node, visit, parent=null) { if(!node || typeof node!=='object') return; if(typeof node.type==='string') visit(node,parent); for(const [k,v] of Object.entries(node)){if(['loc','start','end','comments','tokens','errors'].includes(k))continue;if(Array.isArray(v))v.forEach(x=>walk(x,visit,node));else if(v&&typeof v==='object')walk(v,visit,node);}}
function visual(node){let found=false;function visit(n,top=true){if(!n||typeof n!=='object')return;if(!top&&['FunctionDeclaration','FunctionExpression','ArrowFunctionExpression','ClassDeclaration'].includes(n.type))return;if(n.type==='JSXElement'||n.type==='JSXFragment'||n.type==='CallExpression'&&((n.callee.name==='createElement')||(n.callee.type==='MemberExpression'&&n.callee.object.name==='React'&&n.callee.property.name==='createElement')))found=true;for(const[k,v]of Object.entries(n)){if(['loc','start','end','comments'].includes(k))continue;if(Array.isArray(v))v.forEach(x=>visit(x,false));else if(v&&typeof v==='object')visit(v,false);}}visit(node);return found;}
const records=[];const errors=[];const stories=[];const scannedModules=[];
for(const p of paths.filter(x=>x.startsWith('src/')&&/\.(js|jsx|mjs|ts|tsx)$/.test(x)&&! /\.(test|spec)\./.test(x))){
let ast;try{ast=parser.parse(fs.readFileSync(path.join(root,p),'utf8'),{sourceType:'unambiguous',plugins:['jsx','importAttributes',...(/\.(ts|tsx)$/.test(p)?['typescript']:[])],errorRecovery:false})}catch(e){errors.push({path:p,error:e.message});continue;}
const isStory=p.includes('.stories.');
const symbols=[]; const exports=new Map(); const imports=[]; const jsxNames=new Set();
walk(ast,(n,parent)=>{
if(n.type==='ImportDeclaration')imports.push(n.source.value);
if(n.type==='JSXOpeningElement'&&n.name.type==='JSXIdentifier')jsxNames.add(n.name.name);
if(n.type==='ExportDefaultDeclaration'){const d=n.declaration;exports.set(d.id?.name||d.name||'default','default');}
if(n.type==='ExportNamedDeclaration'){if(n.declaration?.id)exports.set(n.declaration.id.name,n.declaration.id.name);for(const d of n.declaration?.declarations||[])if(d.id?.name)exports.set(d.id.name,d.id.name);for(const s of n.specifiers||[])exports.set(s.local?.name,s.exported?.name);}
let name,body,kind;
if(n.type==='FunctionDeclaration'){name=n.id?.name||'default';body=n;kind='function';}
else if(n.type==='VariableDeclarator'&&n.id.type==='Identifier'&&n.init){let value=n.init; if(['ArrowFunctionExpression','FunctionExpression'].includes(value.type)){name=n.id.name;body=value;kind='function';}else if(value.type==='CallExpression'&&['memo','forwardRef','lazy','dynamic'].includes(value.callee.name||value.callee.property?.name)&&value.arguments?.some(a=>['ArrowFunctionExpression','FunctionExpression'].includes(a.type))){name=n.id.name;body=value.arguments.find(a=>['ArrowFunctionExpression','FunctionExpression'].includes(a.type));kind='wrapped';}else if(['JSXElement','JSXFragment'].includes(value.type)){name=n.id.name;body=value;kind='element';}}
else if(n.type==='AssignmentExpression'&&n.left.type==='MemberExpression'&&n.left.object.name&&n.left.property.name&&['FunctionExpression','ArrowFunctionExpression'].includes(n.right.type)){name=n.left.object.name+'.'+n.left.property.name;body=n.right;kind='compound';}
else if(n.type==='ClassDeclaration'&&n.id){name=n.id.name;body=n;kind='class';}
if(name&&body)symbols.push({name,line:n.loc.start.line,visual:visual(body),kind});
});
if(isStory){stories.push({path:p,stories:[...exports.values()].filter(e=>e&&e!=='default'),imports});continue;}
const items=symbols.filter(s=>s.visual||exports.has(s.name)&&/^[A-Z]/.test(s.name)||jsxNames.has(s.name)).map(s=>({...s,export:exports.get(s.name)||null}));
scannedModules.push({path:p,candidateCount:items.length});
const standardScope=p.startsWith('src/shared/components/')||p.startsWith('src/shared/ui/')||p.startsWith('src/app/')&&!p.startsWith('src/app/api/');
if(standardScope||items.some(s=>s.visual))records.push({path:p,symbols:items,imports,hasJsx:visual(ast),sourceLineCount:fs.readFileSync(path.join(root,p),'utf8').split('\n').length});
}
console.log(JSON.stringify({records,stories,errors,scannedModules}));
